import java.util.*;

public class Main {
    int distinctEchoSubstrings(String text) {
        int n = text.length();
        Set<String> found = new HashSet<>();
        for (int start = 0; start < n; start++) {
            for (int length = 2; start + length <= n; length += 2) {       // only even lengths can possibly split evenly
                int half = length / 2;
                String firstHalf = text.substring(start, start + half);
                String secondHalf = text.substring(start + half, start + length);
                if (firstHalf.equals(secondHalf)) {                            // direct character by character comparison
                    found.add(text.substring(start, start + length));
                }
            }
        }
        return found.size();
    }

    public static void main(String[] args) {
        String text = "abcabcabc";
        Main solution = new Main();
        System.out.println(solution.distinctEchoSubstrings(text));
    }
}

