def distinct_echo_substrings(text):
    n = len(text)
    base, mod = 131, (1 << 61) - 1
    prefix_hash = [0] * (n + 1)
    power = [1] * (n + 1)
    for i in range(n):
        prefix_hash[i + 1] = (prefix_hash[i] * base + ord(text[i])) % mod
        power[i + 1] = (power[i] * base) % mod

    def get_hash(l, r):                                              # hash of text[l:r], computed in O(1)
        return (prefix_hash[r] - prefix_hash[l] * power[r - l]) % mod

    found = set()
    for start in range(n):
        for length in range(2, n - start + 1, 2):
            half = length // 2
            if get_hash(start, start + half) == get_hash(start + half, start + length):
                if text[start:start + half] == text[start + half:start + length]:  # verify to rule out a collision
                    found.add(text[start:start + length])
    return len(found)


if __name__ == "__main__":
    text = "abcabcabc"
    print(distinct_echo_substrings(text))

