public class Main {
    int distinctEchoSubstrings(String text) {
        int n = text.length();
        long base = 131, mod = (1L << 61) - 1;
        long[] prefixHash = new long[n + 1];
        long[] power = new long[n + 1];
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            prefixHash[i + 1] = (prefixHash[i] * base + text.charAt(i)) % mod;
            power[i + 1] = (power[i] * base) % mod;
        }
        Set<String> found = new HashSet<>();
        for (int start = 0; start < n; start++) {
            for (int length = 2; start + length <= n; length += 2) {
                int half = length / 2;
                long hash1 = ((prefixHash[start + half] - prefixHash[start] * power[half]) % mod + mod) % mod;
                long hash2 = ((prefixHash[start + length] - prefixHash[start + half] * power[half]) % mod + mod) % mod;
                if (hash1 == hash2) {
                    String firstHalf = text.substring(start, start + half);
                    String secondHalf = text.substring(start + half, start + length);
                    if (firstHalf.equals(secondHalf)) {                          // verify to rule out a hash collision
                        found.add(text.substring(start, start + length));
                    }
                }
            }
        }
        return found.size();
    }

