#include <bits/stdc++.h>
using namespace std;

int distinctEchoSubstrings(string text) {
    int n = (int)text.size();
    const long long base = 131, mod = (1LL << 61) - 1;
    vector<long long> prefixHash(n + 1, 0), power(n + 1, 1);
    for (int i = 0; i < n; i++) {
        prefixHash[i + 1] = (prefixHash[i] * base + text[i]) % mod;
        power[i + 1] = (power[i] * base) % mod;
    }
    auto getHash = [&](int l, int r) {                                    // hash of text[l:r], computed in O(1)
        return ((prefixHash[r] - prefixHash[l] * power[r - l]) % mod + mod) % mod;
    };
    unordered_set<string> found;
    for (int start = 0; start < n; start++) {
        for (int length = 2; start + length <= n; length += 2) {
            int half = length / 2;
            if (getHash(start, start + half) == getHash(start + half, start + length)) {
                string firstHalf = text.substr(start, half);
                string secondHalf = text.substr(start + half, half);
                if (firstHalf == secondHalf) {                                 // verify to rule out a hash collision
                    found.insert(text.substr(start, length));
                }
            }
        }
    }
    return (int)found.size();
}

int main() {
    string text = "abcabcabc";
    cout << distinctEchoSubstrings(text) << endl;
    return 0;
}
